import re
from typing import List, Dict, Any

# --------------------------------------------------------------------
# Helper functions
# --------------------------------------------------------------------
def _get_node_by_title(doc: Any, title: str):
    """Return the first node in doc whose title matches the given string."""
    for node in doc["nodes"]:
        if node.get("title") == title:
            return node
    return None

def _find_child_by_regex(children: List[Any], pattern: str):
    """Return the first child whose title matches the regex pattern."""
    rgx = re.compile(pattern)
    for c in children:
        if rgx.fullmatch(c.get("title", "")):
            return c
    return None

def _extract_objects(lines: List[str]) -> Dict[str, str]:
    """
    Parse lines like 'Object 0: brown metal sphere (color=brown, material=metal, shape=sphere)'
    into a dictionary mapping object id to description.
    """
    obj_map = {}
    obj_re = re.compile(r"Object\s+(\d+):\s+([^\(]+)\s*\([^\)]+\)")
    for line in lines:
        m = obj_re.match(line.strip())
        if m:
            obj_id, desc = m.group(1), m.group(2).strip()
            obj_map[obj_id] = desc
    return obj_map

def _extract_event_collisions(lines: List[str]) -> List[Dict[str, Any]]:
    """
    Parse collision events from lines like:
    'Frame 24: Object 0 (brown metal sphere) collides with Object 1 (cyan rubber sphere).'
    Returns a list of dicts with time, kind, participants.
    """
    evs = []
    # pattern to capture frame, two object ids
    coll_re = re.compile(
        r"Frame\s+(\d+):\s+Object\s+(\d+).*?collides with Object\s+(\d+)", re.IGNORECASE)
    for line in lines:
        m = coll_re.search(line)
        if m:
            frame = int(m.group(1))
            id1 = m.group(2)
            id2 = m.group(3)
            evs.append({"time": float(frame), "kind": "collision",
                        "participants": [id1, id2]})
    return evs

def _extract_frames(lines: List[str]) -> List[int]:
    """
    Extract frame numbers from lines that start with 'Frame <n>:'.
    """
    frames = []
    frame_re = re.compile(r"Frame\s+(\d+):")
    for line in lines:
        m = frame_re.search(line)
        if m:
            frames.append(int(m.group(1)))
    return frames


# --------------------------------------------------------------------
# Public API
# --------------------------------------------------------------------
def entities(doc: Any, scope: str) -> List[Dict[str, str]]:
    """
    Return a list of distinct entities in the given scope.
    Each entity is a dict with 'id' and 'description'.
    """
    scope_node = _get_node_by_title(doc, scope)
    if not scope_node:
        return []

    # Find the Objects list node
    children_nodes = [c for c in doc["nodes"] if c.get("parent_id") == scope_node["node_id"]]
    obj_node = _find_child_by_regex(children_nodes, rf"{re.escape(scope)}: Objects")
    if not obj_node or obj_node.get("kind") != "list":
        return []

    obj_dict = _extract_objects(obj_node.get("lines", []))
    return [{"id": oid, "description": desc} for oid, desc in obj_dict.items()]


def recorded_end(doc: Any, scope: str) -> float:
    """
    Return the last time point covered by the scope's records.
    """
    scope_node = _get_node_by_title(doc, scope)
    if not scope_node:
        return 0.0

    children_nodes = [c for c in doc["nodes"] if c.get("parent_id") == scope_node["node_id"]]
    max_frame = -1

    # Check Events
    events_node = _find_child_by_regex(children_nodes, rf"{re.escape(scope)}: Events")
    if events_node and events_node.get("kind") == "list":
        frames = _extract_frames(events_node.get("lines", []))
        max_frame = max(max_frame, max(frames, default=-1))

    # Check Motion log (table)
    motion_node = _find_child_by_regex(children_nodes, rf"{re.escape(scope)}: Motion log")
    if motion_node and motion_node.get("kind") == "table":
        rows = motion_node.get("table", {}).get("rows", [])
        for row in rows:
            try:
                frame = int(row[0])
                if frame > max_frame:
                    max_frame = frame
            except (ValueError, IndexError):
                continue

    return float(max_frame) if max_frame >= 0 else 0.0


def observed_events(doc: Any, scope: str) -> List[Dict[str, Any]]:
    """
    Return a list of interaction events (collisions) in the given scope, in time order.
    Each event is a dict with 'time', 'kind', and 'participants' (entity ids).
    """
    scope_node = _get_node_by_title(doc, scope)
    if not scope_node:
        return []

    children_nodes = [c for c in doc["nodes"] if c.get("parent_id") == scope_node["node_id"]]
    events_node = _find_child_by_regex(children_nodes, rf"{re.escape(scope)}: Events")
    if not events_node or events_node.get("kind") != "list":
        return []

    collision_events = _extract_event_collisions(events_node.get("lines", []))
    # Sort by time
    collision_events.sort(key=lambda e: e["time"])
    return collision_events


